"""Build the fixed C1 user-run notebook; no model or media execution."""
from pathlib import Path
import argparse,ast,json,re
ROOT=Path(__file__).resolve().parents[1]
OUTPUT=ROOT/'notebooks/video_overlap_tube_state_c1_v1_colab.ipynb'
MARKDOWN='# Video-Overlap-Tube-State C1 candidate\n\nRun all executes one copper-kettle source, OFF / PAYLOAD_MULTI / OVERLAP_MULTI, each with a complete independent 50-step native Wan trajectory. Both marked arms use fresh conditional updates at25..49. Existing four-channel repeated32-bit payload stays unchanged. The overlap pilot uses real spatial channel4, four4x4 blocks and four orthogonal age subspaces; actual summed pilot update has an L2 cap1 per step. Target norm1, actual update norm and25-step accumulated norms are distinct. Total arm budgets are not matched.\n\nThree source MP4s each yield FULL_RESAVED181 and CROP4/5/6/7_129 through the same second codec. Every view is independently decoded from saved MP4 and re-encoded in four RGB phases. Full common support is44 regular latents (new namespace); crop support31. Extra normalized rows are saved but do not enter primary scores. This does not reuse old45-row full scoring.\n\nFixed outputs:3 source,15 derived videos;60 normalized tensors;120 phase/key path files and repeated-payload reads;30 searches;60 truth joins. Each phase retains the complete finite zero/one-event catalog, structural exclusions, exact equivalences and numeric ties:357480 catalog slots,92016 valid costs. Payload never selects a path. All paths are uncalibrated and unaccepted; wrong-key/OFF fits are not FPR evidence. Raw evidence is committed before truth joins and quality reads.\n\nThis tests survival and false edit fitting in actual full/crop media. The CPU ideal additive mechanism is not a real-video result. Position-dependent payload is reserved. C2 real4-RGB edit helpers are prepared but are not executed by this notebook. A crop resets VAE context; nominal stride4 is not the full receptive field.\n\nCurrent Python, compatible working Torch pair and serial fresh children are reused; no venv, Python-version or GPU-model hard gate. No agent model/GPU/Colab execution. Source is an unpublished draft until the main session publishes and binds its immutable SHA.\n'
SETUP="from pathlib import Path\nimport datetime,hashlib,json,os,subprocess,sys,traceback\nSTAMP=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')\nOUTPUT=Path('/content/drive/MyDrive/Video-WM/Video-Overlap-Tube-State-C1-V1')/STAMP\nOUTPUT.mkdir(parents=True,exist_ok=False)\nREPO=Path('/content/SC-SSTW-OVERLAP-TUBE-'+STAMP)\nRUN_OUTPUT=OUTPUT/'fixed_reference'\nPYTHON=sys.executable\nARMS=('OFF','PAYLOAD_MULTI','OVERLAP_MULTI');KEYS=('CORRECT','WRONG')\nVIEW_LENGTHS={'FULL_RESAVED181':181,**{f'CROP{i}_129':129 for i in range(4,8)}}\nVIEWS=tuple(VIEW_LENGTHS)\nFIXED=dict(source_cases=1,arms=3,source_mp4=3,derived_mp4=15,normalized=60,phase_path_searches=120,phase_payload_reads=120,\n primary_searches=30,posthoc=60,catalog_slots=357480,valid_costs=92016,structural_exclusions=265464,pilot_positives=5,pilot_negatives=25)\nsetup=dict(status='SETUP_STARTED',source_sha=SOURCE_SHA,fixed_denominator=FIXED,\n terminal_diagnostics={a+'/'+k:{'status':'NOT_RUN_SETUP'} for a in ARMS for k in KEYS},\n generation={a:{'status':'NOT_RUN_SETUP'} for a in ARMS},sources={a:{'status':'NOT_RUN_SETUP'} for a in ARMS},\n views={a+'/'+v:{'status':'NOT_RUN_SETUP'} for a in ARMS for v in VIEWS},\n normalized={a+'/'+v+'/'+str(g):{'status':'NOT_RUN_SETUP'} for a in ARMS for v in VIEWS for g in range(4)},\n phase_reads={a+'/'+v+'/'+str(g)+'/'+k:{'status':'NOT_RUN_SETUP','expected_catalog_slots':45*(2*((VIEW_LENGTHS[v]-4)//4)-1)} for a in ARMS for v in VIEWS for g in range(4) for k in KEYS},\n searches={a+'/'+v+'/'+k:{'status':'NOT_RUN_SETUP','accepted_payload':False} for a in ARMS for v in VIEWS for k in KEYS},\n evaluations={a+'/'+v+'/'+k+'/'+t:{'status':'NOT_RUN_SETUP'} for a in ARMS for v in VIEWS for k in KEYS for t in ('REGISTERED','WRONG_MESSAGE')})\ndef write_json(path,value):\n    temp=path.with_suffix(path.suffix+'.tmp');temp.write_text(json.dumps(value,indent=2)+'\\n');os.replace(temp,path)\ndef failed(stage,exc):\n    setup.update(status='SETUP_FAILED',stage=stage,error=f'{type(exc).__name__}: {exc}')\n    write_json(OUTPUT/'setup_receipt.json',setup)\n    write_json(OUTPUT/'setup_failure.json',dict(stage=stage,error=str(exc),traceback=traceback.format_exc()))\ndef logged(command,stage,cwd=None,check=True):\n    try:\n        with (OUTPUT/'execution.log').open('a') as log:\n            log.write('COMMAND '+repr(command)+'\\n');log.flush()\n            child=subprocess.Popen(command,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)\n            for line in child.stdout:print(line,end='',flush=True);log.write(line);log.flush()\n            code=child.wait();log.write('EXIT '+str(code)+'\\n')\n        if check and code:raise subprocess.CalledProcessError(code,command)\n        return code\n    except Exception as exc:failed(stage,exc);raise\nwrite_json(OUTPUT/'setup_receipt.json',setup)\nprint('Fixed output:',OUTPUT)\nif SOURCE_SHA is None:\n    error=RuntimeError('Unpublished draft: bind verified published source SHA before Run all')\n    failed('SOURCE_BINDING',error);raise error\n"
ENVIRONMENT="try:\n    logged(['git','clone','--filter=blob:none','https://github.com/RICHAAARC/SC-SSTW.git',str(REPO)],'SOURCE_CLONE')\n    logged(['git','-C',str(REPO),'fetch','origin',SOURCE_SHA],'SOURCE_FETCH')\n    logged(['git','-C',str(REPO),'checkout','--detach',SOURCE_SHA],'SOURCE_CHECKOUT')\n    actual=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip()\n    dirty=subprocess.check_output(['git','-C',str(REPO),'status','--porcelain'],text=True)\n    if actual!=SOURCE_SHA or dirty:raise RuntimeError('source SHA/clean checkout mismatch')\n    write_json(OUTPUT/'source_receipt.json',dict(source_sha=actual,clean=True))\n    torch_ok=logged([PYTHON,'-c','import torch,torchvision; print(torch.__version__,torchvision.__version__)'],'TORCH_PROBE',check=False)==0\n    if not torch_ok:\n        logged([PYTHON,'-m','pip','install','--upgrade','torch','torchvision'],'TORCH_REPAIR')\n    logged([PYTHON,'-m','pip','install','-r',str(REPO/'experiments/wan_state_clock/requirements-grow-video-reference.txt')],'DEPENDENCIES')\n    dependency_code=logged([PYTHON,'-m','pip','check'],'DEPENDENCY_REPORT',check=False)\n    setup['dependency_check_returncode']=dependency_code\n    if dependency_code:print('Metadata conflicts retained; actual imports determine availability.')\n    (OUTPUT/'environment_freeze.txt').write_text(subprocess.check_output([PYTHON,'-m','pip','freeze'],text=True))\n    import_code='import json,torch; from diffusers import WanPipeline,AutoencoderKLWan,UniPCMultistepScheduler; from experiments.wan_state_clock.video_overlap_tube_state_c1_run import environment; r=environment(); r.update(cuda_available=torch.cuda.is_available()); print(json.dumps(r))'\n    env=json.loads(subprocess.check_output([PYTHON,'-c',import_code],cwd=REPO,text=True))\n    write_json(OUTPUT/'environment_receipt.json',env)\n    if not env['cuda_available']:print('CUDA unavailable: CPU path selected; much slower.')\n    logged(['ffmpeg','-version'],'FFMPEG_PROBE');logged(['ffprobe','-version'],'FFPROBE_PROBE')\n    setup.update(status='SETUP_COMPLETE',python_executable=PYTHON,environment_strategy='current_python_fresh_children')\n    write_json(OUTPUT/'setup_receipt.json',setup)\nexcept Exception as exc:failed('SOURCE_OR_ENVIRONMENT',exc);raise\n"
RUN="try:\n    from google.colab import userdata\n    token=userdata.get('HF_TOKEN')\n    if token:os.environ['HF_TOKEN']=token\nexcept Exception:\n    pass\nfinally:\n    token=None\ncommand=[PYTHON,'-u','-m','experiments.wan_state_clock.video_overlap_tube_state_c1_run','--output',str(RUN_OUTPUT)]\ntry:\n    returncode=logged(command,'FIXED_RUN',cwd=REPO,check=False)\n    RESULT_PATH=RUN_OUTPUT/'result.json'\n    write_json(OUTPUT/'execution_receipt.json',dict(command=command,returncode=returncode,result_path=str(RESULT_PATH),result_exists=RESULT_PATH.is_file()))\n    if not RESULT_PATH.is_file():raise RuntimeError('No runner result; full setup denominator is retained')\n    setup.update(status='SUPERSEDED_BY_RESULT',result_path=str(RESULT_PATH));write_json(OUTPUT/'setup_receipt.json',setup)\nexcept Exception as exc:failed('RUNNER',exc);raise\n"
DISPLAY="result=json.loads(RESULT_PATH.read_text())\nif result['source_sha']!=SOURCE_SHA or result['fixed_denominator']!=FIXED:raise RuntimeError('result identity/denominator mismatch')\nprint(result['status'],result['counts'])\nfor name,row in result['searches'].items():\n    print(name,row['status'],'canonical diagnostic=',row.get('canonical'),'top hypotheses=',len(row.get('top',[])))\nfor name,row in result['evaluations'].items():\n    print(name,row['status'],'truth in top=',row.get('truth_in_top'),'canonical event=',row.get('canonical_event'),'diagnostic payload errors=',row.get('diagnostic_bit_errors'))\nprint('All state paths remain UNCALIBRATED_DIAGNOSTIC and unaccepted; unique finite-model argmin is not confidence.')\nprint('Quality diagnostics:',result.get('quality'))\nprint('Evidence ceiling:',result['evidence_ceiling'])\nfrom IPython.display import Video,display\nfor name,row in list(result['sources'].items())+list(result['views'].items()):\n    print(name,row['status'])\n    if row['status']=='SAVED' and Path(row['path']).is_file():\n        try:display(Video(str(row['path']),embed=True))\n        except Exception as exc:print('Preview unavailable; saved MP4 remains at',row['path'],type(exc).__name__,str(exc))\nprint('Inspect visible quality separately; recovery results do not imply quality PASS.')\n"


def build(source_sha=None,output=OUTPUT):
    if source_sha is not None and not re.fullmatch('[0-9a-f]{40}',source_sha):raise ValueError('published immutable source SHA required')
    sources=[('code',"from google.colab import drive\ndrive.mount('/content/drive')\n"),('markdown',MARKDOWN.replace('Source is an unpublished draft until the main session publishes and binds its immutable SHA.', ('Published source: `'+source_sha+'`. This notebook checks out that immutable source commit.' if source_sha else 'UNPUBLISHED DRAFT: source must be published and its immutable SHA verified before binding.'))),
      ('code',f'SOURCE_SHA = {source_sha!r}\n'+SETUP),('code',ENVIRONMENT),('code',RUN),('code',DISPLAY)]
    cells=[]
    for i,(kind,text) in enumerate(sources):
        cell=dict(cell_type=kind,id=f'overlap-tube-c1-{i}',metadata={},source=text.splitlines(keepends=True))
        if kind=='code':ast.parse(text);cell.update(outputs=[],execution_count=None)
        cells.append(cell)
    value=dict(nbformat=4,nbformat_minor=5,cells=cells,metadata=dict(kernelspec=dict(display_name='Python3',language='python',name='python3'),
      language_info=dict(name='python'),candidate_binding=dict(source_sha=source_sha,status='PUBLISHED_SHA_BOUND' if source_sha else 'UNPUBLISHED_DRAFT',execution='User-run only; no agent GPU/Colab execution')))
    Path(output).write_text(json.dumps(value,indent=1)+'\n');return Path(output)

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--source-sha');parser.add_argument('--output',type=Path,default=OUTPUT)
    args=parser.parse_args();print(build(args.source_sha,args.output))
